        static Dictionary<string, Glyph> byChar;

        /// <summary>The glyph's metrics, or null when the templates do not know it.</summary>
        public static Glyph Find(string ch)
        {
            if (byChar == null)
            {
                var d = new Dictionary<string, Glyph>();
                foreach (Glyph g in Glyphs) d[g.Ch] = g;
                byChar = d;
            }
            return ch != null && byChar.TryGetValue(ch, out Glyph found) ? found : null;
        }
    }
